const { Client } = require('undici');

const client = new Client(process.env.PRICING_URL, {
  requestTimeout: 5000,
  maxKeepAliveTimeout: 30000
});

async function getQuote(sku) {
  const { statusCode, body } = await client.request({
    path: `/quotes/${encodeURIComponent(sku)}`,
    method: 'GET'
  });
  let data = '';
  for await (const chunk of body) data += chunk;
  if (statusCode !== 200) throw new Error(`pricing ${statusCode}`);
  return JSON.parse(data);
}

module.exports = { getQuote };
